# Refined prediction with correct directional behavior

def predict_from_sources_v2(sources, grid_rows=12, grid_cols=8):
    result = [[0] * grid_cols for _ in range(grid_rows)]

    for sr, sc in sources:
        # Consider rows affected by this source
        min_r = max(0, sr - 2)
        max_r = min(grid_rows, sr + 3)

        for r in range(min_r, max_r):
            dr = r - sr  # signed: negative above, positive below

            if dr < 0:  # Above source: wider spread
                # At dr = -1: offsets ±2
                # At dr = -2: offsets ? (maybe ±3 or just don't extend?)
                if dr == -1:
                    offsets = [-2, 2]
                elif dr == -2:
                    offsets = [-3, 3]  # Or stop here?
                else:
                    offsets = []
            elif dr == 0:  # Source row itself
                offsets = [-1, 1]  # Medium spread
            else:  # Below source: narrow/center
                # At dr = +1: offset 0 (just center)
                # At dr = +2: maybe no extension?
                if dr == 1:
                    offsets = [0]
                else:
                    offsets = []

            for dc in offsets:
                c = sc + dc
                if 0 <= c < grid_cols:
                    result[r][c] = 4

    return result

